// Reine Umformung - die Markdown-Datei hat der Dienst gebaut.
// Hier wird nur in das Format gebracht, das der Master-Ablauf erwartet.
// Bewusst ohne Logik: Alles, was den Inhalt betrifft, steckt in
// mk_md.baue_markdown() und gilt damit fuer die Skript-Kette und fuer
// n8n gleichermassen.
return $input.all().map((item) => {
  const a = item.json;
  const name = a.dateiname || 'dokument.md';
  return {
    json: {
      markdown_filename: name,
      markdown_path: '/files/anythingllm/' + name,
      markdown_content: a.markdown,
      zeichen: a.zeichen,
      seiten: a.seiten,
      tags: a.tags,
      keywords: a.keywords,
      methoden: a.methoden,
    },
    binary: {
      data: {
        data: Buffer.from(a.markdown, 'utf8').toString('base64'),
        mimeType: 'text/markdown',
        fileName: name,
      },
    },
  };
});
